#!/usr/bin/env python3
"""Write RESULTS.md from runs/summary.json, runs/ledger-w.json and runs/progress.log. Every number in RESULTS.md comes
from those committed files; the fixed prose (deviations, what is not established, raw data) is read from a text file.
Usage: make_results.py <tail.md>   (the committed prose file is results_tail.md)"""
import json, sys
from pathlib import Path

HERE = Path(__file__).resolve().parent; R = HERE / "runs"
S = json.load(open(R / "summary.json")); LW = json.load(open(R / "ledger-w.json"))
B = S["baseline"]; A = S["arms"]; V = S["verdicts"]; ls = S["layer_set_done"]; K = S["k_rule"]
prog = (R / "progress.log").read_text().splitlines()
tail = open(sys.argv[1]).read()
complete = ls in ("full", "r33") and S["baseline_complete"]
nb = len(S["layers_baseline"]); nl = len(S["layers_arms"])
pct = lambda x: f"{100 * x:.2f}%"
g = lambda x: "n/a" if x is None else f"{x:.3g}"
i_ = lambda x: f"{int(x):,}"
a, m = B["input_layernorm"], B["post_attention_layernorm"]
passing = [n for n, v in V.items() if v["verdict"] == "PASS"]
if not complete: head = ("PARTIAL: the run stopped itself on the registered free-disk floor before finishing its layer set. No arm has a registered verdict. "
                         "Every arm already has failing layers among those done (section 2).")
elif passing: head = f"H HOLDS on the layers measured: arm{'s' if len(passing) > 1 else ''} {', '.join(passing)} pass{'' if len(passing) > 1 else 'es'} (class and per-layer fidelity bar)."
else: head = "NEGATIVE: H does not hold. No registered arm is both in class and inside the per-layer fidelity bar."
L = ["# RESULTS: 20261112-148-norm-class", "",
     "Issue #148. PREREG: [PREREG.md](PREREG.md) (first commit 11b9889f, alone; Amendment A-1 before the registered run, A-2 during it). Code and commands: [README.md](README.md). "
     "Generated by `make_results.py` from `runs/summary.json` and `runs/ledger-w.json`. All numbers are measured, unreplicated, from one deterministic CPU run; "
     "the arm W ledger cost is counted, not measured.", "",
     f"**{head}**", "",
     f"Scope actually run: baseline on {nb} of 64 layers; arms on {nl} layers (layer set: {ls}"
     + ("; the registered reduced set R33, PREREG Kill criterion and A-1" if ls == "r33" else "")
     + (f": the members of the reduced set R33 up to layer {max(S['layers_arms'])}; the run ended after layer {max(S['layers_baseline'])}, see Deviations" if ls == "partial" else "")
     + "); abliterated checkpoint; 6 prompts, 672 tokens (includes p03-repeat-word); "
     "open loop (each layer starts from the float64 stream). No logits and no token agreement were computed.", "",
     "## 1. Plain summary", ""]
both_all = a["layers_with_any_over"] == a["n_layers"] and m["layers_with_any_over"] == m["n_layers"]
why = lambda v: "the run is partial" if not complete else v.get("why", "not measured")
rows_all = a["total"]["rows_over"] == a["total"]["rows"] and m["total"]["rows_over"] == m["total"]["rows"]
L += [f"- Both pre-norm outputs are over the design's public class in {'every' if both_all else 'most'} measured layer"
      f"{'' if both_all else 's'}. The mixer input (input_layernorm output) is over 2,047 on {pct(a['share_over_2047'])} of entries "
      f"(max {i_(a['max_q12'])}, layer {a['max_layer']}). The MLP input (post_attention_layernorm output) is over on {pct(m['share_over_2047'])} (max {i_(m['max_q12'])}, layer {m['max_layer']})."
      + (f" Every one of the {a['total']['rows']:,} token rows (layers done x 672 tokens) has at least one entry over the class, on both norms." if rows_all else "")]
for name in ("C", "S", "W"):
    v = V[name]; arm = v.get("arm")
    if arm is None or arm not in A or not A[arm]["n_layers"]:
        L.append(f"- Arm {name} (smaller scale): **no verdict (partial)**. Its k rule needs the baseline of all 64 layers. Ladder points measured: "
                 + "; ".join(f"S{k} (scale 2^{k}): {A['S' + str(k)]['layers_pass']} of {A['S' + str(k)]['n_layers']} layers meet the bar, per-layer median error from "
                             f"{g(A['S' + str(k)]['r_median_over_layers']['min'])} to {g(A['S' + str(k)]['r_median_over_layers']['max'])}" for k in (3, 4, 5)) + "."); continue
    x = A[arm]; t = x["totals"]; rm = x["r_median_over_layers"]
    label = {"C": "clamp to 2,047 at 2^12", "S": f"scale 2^{arm[1:]}, no clamp", "W": "2^12, class widened to 2^18, no clamp"}[name]
    cls = ("every entry in class" if x["in_class_on_layers_done"] else f"{t['n_out_of_class']:,} entries outside its class")
    L.append(f"- Arm {name} ({label}): **{v['verdict'] if complete else 'no verdict (partial)'}**. {cls[0].upper() + cls[1:]}; {x['layers_pass']} of {x['n_layers']} layers meet the fidelity bar; "
             f"per-layer median error from {g(rm['min'])} to {g(rm['max'])}; largest single value {g(x['r_max_over_layers'])} (layer {x['worst_layer']})."
             + (f" It clamps {t['n_clamped_a'] + t['n_clamped_m']:,} of {t['n_entries']:,} entries." if name == "C" else ""))
L += ["", "## 2. Verdict against the registration", "",
      "Bar (PREREG Acceptance threshold): the arm is IN-CLASS (no norm-output entry outside its registered class on any measured layer and token) and every measured layer has "
      "median over the 6 prompts of r <= 1e-3 and max of r <= 1e-2, where r is the relative L2 of the layer's output stream against float64.", "",
      "| arm | measured as | class registered | in class (layers done) | layers meeting the bar (of layers done) | verdict |", "|---|---|---|---|---|---|"]
CL = {"C": "\\|q\\| <= 2,047 at 2^12 (by construction)", "S": "\\|q\\| <= 2,047 at 2^k*, shifts in 1..24", "W": "\\|q\\| < 2^18 at 2^12"}
for name in ("C", "S", "W"):
    v = V[name]; arm = v.get("arm")
    if arm is None or arm not in A or not A[arm]["n_layers"]:
        L.append(f"| {name} | not named (k rule not evaluable) | {CL[name]} | n/a | n/a | NO VERDICT ({why(v)}) |"); continue
    x = A[arm]
    L.append(f"| {name} | {arm} | {CL[name]} | {'yes' if x['in_class_on_layers_done'] else 'NO'} | {x['layers_pass']} of {x['n_layers']} | {v['verdict']}{' (' + why(v) + ')' if 'why' in v else ''} |")
L += ["", f"k rule for arm S (PREREG): M = {K['M']:.6g} is the largest |norm output| of the baseline over both norms"
      + (f", all 64 layers and 672 tokens; k* = {K['k_star']}, so arm S is the run's S{K['k_star']}" + ("." if K["in_ladder"] else ", which is outside the measured ladder (3, 4, 5): arm S has no verdict.")
         if K["evaluable"] else "; the rule needs the baseline of all 64 layers, which this run does not have, so k* is not evaluated."),
      "" if complete else "(`runs/summary.json` carries one generic reason string for every NO VERDICT, \"run incomplete, baseline incomplete or determinism not shown\". Here the cause is the incomplete run; the determinism check passed.)",
      f"Determinism: arm C computed twice on p01 and p09, layer outputs {'bit-identical in all ' + str(S['determinism']['layers_checked']) + ' arm layers' if S['determinism']['all_bit_equal'] else 'NOT shown bit-identical'}.",
      ""]
if not complete:
    kmax = max(k for k in range(-40, 13) if round(2.0 ** k * K["M"]) <= 2047)
    lad = [f"S{k}" for k in (3, 4, 5) if k <= kmax]
    xc, xw = A["C"], A["W"]
    L += ["**What the layers done already settle (arithmetic on the registered rule, not a registered verdict).** The bar needs every measured layer to pass, "
          "so a failing layer among those done cannot be undone by the layers that were not run.",
          f"- Arm C: in class by construction; {len(xc['layers_fail'])} of {xc['n_layers']} layers done fail the fidelity bar.",
          f"- Arm W: {xw['totals']['n_out_of_class']:,} entries at or over 2^18 in its own rows on the {xw['n_layers']} arm layers ({xw['totals']['baseline_ge_2e18_all_baseline_layers']:,} in the baseline of the "
          f"{nb} layers done), so it is out of its registered class under either reading of A-2; and {len(xw['layers_fail'])} of {xw['n_layers']} layers done fail the fidelity bar.",
          f"- Arm S: M over the {nb} baseline layers done is {K['M']:.6g}. More layers can only raise M, so the rule's k is at most {kmax}. The measured ladder points at or under that, "
          + " and ".join(f"{s} ({len(A[s]['layers_fail'])} of {A[s]['n_layers']} layers done fail the bar)" for s in lad)
          + (": every one of them has failing layers." if all(A[s]["layers_fail"] for s in lad) else ": not all of them have failing layers, so arm S is NOT settled by the layers done.")
          + " If the rule's k came out under 3 the arm would be unmeasured and would have no verdict.",
          ("- So no completion of this run could have given any arm a PASS, and it could not have shown H to hold. This says nothing about an arm S at a scale below the ladder, which was not measured."
           if (xc["layers_fail"] and xw["layers_fail"] and all(A[s]["layers_fail"] for s in lad)) else "- The layers done do not settle every arm."), ""]
L += ["## 3. Baseline: both pre-norm outputs at 2^12 (item 1 of the issue)", "",
      "q12 = RNE(2^12 x norm output) on the float64 stream. n = layers x 672 tokens x 5,120 channels. Supports both readings of section 5 (it is the class question).", "",
      "| norm output | layers | entries n | over 2,047 | share | per-layer share: median (min to max) | layers with any entry over | token rows with any entry over | max \\|q12\\| | at layer, prompt | >= 2^15 | >= 2^17 | >= 2^18 |",
      "|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
for key, lab in (("input_layernorm", "input_layernorm (mixer input a)"), ("post_attention_layernorm", "post_attention_layernorm (MLP input m)")):
    b = B[key]; t = b["total"]; s = b["share_per_layer"]
    L.append(f"| {lab} | {b['n_layers']} | {t['n']:,} | {t['over']:,} | {pct(b['share_over_2047'])} | {pct(s['median'])} ({pct(s['min'])} to {pct(s['max'])}) | {b['layers_with_any_over']} of {b['n_layers']} | "
             f"{t['rows_over']:,} of {t['rows']:,} | {i_(b['max_q12'])} | {b['max_layer']}, {b['max_prompt']} | {t['ge15']:,} | {t['ge17']:,} | {t['ge18']:,} |")
mrow = {r["layer"]: r for r in m["layers"]}
if 26 in mrow and 30 in mrow:
    L += ["", f"Consistency with PR #138 (descriptive; a different stream and prompt set, so equality is not expected): the MLP input maximum here is {i_(mrow[26]['max_q12'])} at layer 26 and "
          f"{i_(mrow[30]['max_q12'])} at layer 30, on the float64 stream and 6 prompts; PR #138 RESULTS reports 142,651 at layer 26 and 148,536 at its post-cutoff layer 30, on its integer path and 10 prompts."]
L += ["", "Per-layer rows (share and maximum for both norms, every layer): [runs/summary.md](runs/summary.md), section \"Per layer\". Raw: `runs/baseline.jsonl`.", "",
      "## 4. Arms: per-layer output error and class checks (items 2 and 3 of the issue)", "",
      "r = ||(x + out_arm) - (x + out_float64)|| / ||x + out_float64|| per (layer, prompt), all tokens of the prompt. Spread is over the 6 prompts per layer, then over layers. "
      "S3, S4, S5 are the ladder points of arm S; only the one the k rule names carries a verdict.", "",
      "| arm | layers n | layers meeting the bar | per-layer median r: median over layers (min to max) | largest r (layer) | norm-output entries n | outside its class | clamped: mixer input / MLP input | max \\|q\\|: mixer input / MLP input | public shifts used | >= 2^15 / >= 2^17 / >= 2^18 |",
      "|---|---|---|---|---|---|---|---|---|---|---|"]
for arm in ("C", "S3", "S4", "S5", "W"):
    x = A[arm]
    if not x["n_layers"]: continue
    t = x["totals"]; rm = x["r_median_over_layers"]
    L.append(f"| {arm} | {x['n_layers']} | {x['layers_pass']} | {g(rm['median'])} ({g(rm['min'])} to {g(rm['max'])}) | {g(x['r_max_over_layers'])} ({x['worst_layer']}) | {t['n_entries']:,} | {t['n_out_of_class']:,} | "
             f"{t['n_clamped_a']:,} / {t['n_clamped_m']:,} | {i_(t['max_qa'])} / {i_(t['max_qm'])} | {t['shifts_min']} to {t['shifts_max']} | {t['n_ge_2e15']:,} / {t['n_ge_2e17']:,} / {t['n_ge_2e18']:,} |")
L += ["", "**Caveat on the bar (by construction of the arms, not a registered claim).** Arm W changes a norm output only by rounding it at 2^12, so the rest of its difference from float64 is "
      f"PR #138's integer MLP itself. Its per-layer median r runs from {g(A['W']['r_median_over_layers']['min'])} to {g(A['W']['r_median_over_layers']['max'])}, around the registered 1e-3, and "
      f"{len(A['W']['layers_fail'])} of {A['W']['n_layers']} layers fail the bar. So the registered bar is about as tight as the unchanged MLP lowering, and an arm failing it is not by itself evidence "
      "against that arm's norm arithmetic. Compare each arm's r with arm W's on the same layers; `d` in `runs/arms.jsonl` is the arm's distance to arm W."]
L += ["", "Layers failing the bar, per arm: " + "; ".join(f"{arm}: {('none' if not A[arm]['layers_fail'] else ', '.join(str(v) for v in A[arm]['layers_fail']))}" for arm in ("C", "S3", "S4", "S5", "W") if A[arm]["n_layers"]) + ".",
      "", "Per-layer r (median / max over prompts) for every arm: [runs/summary.md](runs/summary.md). The stricter ratio c (against the layer's own contribution), the distance d to arm W, and the mixer and MLP parts are in `runs/arms.jsonl` and `runs/summary.json`.", "",
      "### MLP range counters and SiLU v1 domain exits, per arm (recorded counts, no bar)", "",
      "| arm | hidden entries n | SiLU key outside [-8, 8) (saturated here; a reject under v1) | max \\|gw\\| | max \\|u\\| | max \\|h\\| | gw / u / h >= 2^18 | any of them >= 2^23 | max \\|out\\| | out >= 2^31 | max down accumulator (log2) |",
      "|---|---|---|---|---|---|---|---|---|---|---|"]
import math
for arm in ("C", "S3", "S4", "S5", "W"):
    x = A[arm]
    if not x["n_layers"]: continue
    t = x["totals"]
    L.append(f"| {arm} | {t['n_hidden']:,} | {t['silu_exits']:,} | {i_(t['max_gw'])} | {i_(t['max_u'])} | {i_(t['max_h'])} | {t['n_gw_ge_2e18']:,} / {t['n_u_ge_2e18']:,} / {t['n_h_ge_2e18']:,} | {t['n_gwuh_ge_2e23']:,} | "
             f"{i_(t['max_out'])} | {t['n_out_ge_2e31']:,} | {math.log2(t['max_acc_down']):.2f} |")
L += ["", "## 5. Which reading each number supports (DESIGN 10, an open design decision this lane does not make)", "",
      "| number | integer-served, exact match | float-served, clipped gap |",
      "|---|---|---|",
      "| baseline share and maximum over 2,047 (section 3) | decides: an input outside the class is a position the statement cannot admit, so it cannot be proved | decides, for the same reason |",
      "| arm class verdict, clamped counts, shifts (section 4) | decides provability under that arm | decides provability under that arm |",
      "| arm r, c, d (section 4) | does **not** gate provability: the proof would be about the integer model as it is. It says how far one integer layer is from Qwen's float layer, a model-quality question for whoever serves the integer model | a **necessary** per-layer condition for the integer model to stay close to the served float model. Not sufficient: open loop, no logits |",
      "| SiLU domain exits | each is a position v1 cannot prove (reject semantics) unless the table saturates or widens | the same |",
      "| arm W ledger cost (section 6) | cost of admitting the wider class | the same |",
      "", "## 6. Arm W: cost of the wider class, counted from the bound ledger (not built, not measured)", "",
      "`ledger_w.py` re-sums the two no-wrap rows of `bounds.py` that contain the public norm class, with every factor at its class edge. No activation is read.", "",
      "| public norm class | signed bits | in_proj and MLP gate / up row: log2 of the bound | below 2^63 | headroom (bits) | lookup keys if the value were a committed cell | relations per committed cell |",
      "|---|---|---|---|---|---|---|"]
for c in LW["classes"]:
    L.append(f"| {c['A_label']} | {c['signed_bits']} | {c['in_proj_row']['log2']} | {'yes' if c['in_proj_row']['below_2_63'] else 'NO'} | {c['in_proj_row']['headroom_bits']} | {c['keys_if_committed_cell']['total']} | {c['keys_if_committed_cell']['relations']} |")
L += ["", "In M3a the norm outputs are public statement words checked at admission, so a wider class adds no cell there; only the two rows above change and both stay below 2^63. "
      "In the full-model form a norm output is a committed cell and the last two columns count what its class check would need per value. This is a count on class edges, not a build.", "",
      "## 7. Run facts", "", "```"] + prog + ["```", ""]
L.append(tail.strip("\n")); L.append("")
(HERE / "RESULTS.md").write_text("\n".join(L))
print("RESULTS.md written;", head)
